import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updatePoll } from "../handlers/updatePoll";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePollEntityType } from "../types/SpacePollEntityType";
import type { UpdatePollRequest } from "../types/UpdatePollRequest";

type Data = Awaited<ReturnType<typeof updatePoll>>;
type Vars = { spacePk: SpacePartition; pollSk: SpacePollEntityType; req: UpdatePollRequest };

export function useUpdatePoll(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updatePoll(vars.spacePk, vars.pollSk, vars.req),
    ...options,
  });
}
